def render(row):
    name,trigger,sources,steps,outputs,limits=row
    title=" ".join(x.capitalize() if x not in {"seo","ai"} else x.upper() for x in name.split("-"))
    numbered="\n".join(f"{i}. {step}" for i,step in enumerate(steps,1))
    output_lines="\n".join(f"- {x}." for x in outputs)
    return f'''---
name: {name}
description: "Use when {trigger}."
---

# {title}

## Purpose

Use this skill for {trigger}. Its primary sources are {sources}.

## Workflow

{numbered}

## Required Output

{output_lines}

Every output must name target/scope, evidence class, retrieval or run time,
unavailable checks, permission mode, and comparison baseline where applicable.

## Boundaries

{limits} Preserve OBSERVE/PROPOSE/ACT boundaries, provider cost and credential
limits, stable finding identity, and the distinction among finding,
recommendation, action, and outcome. Never store credentials or fabricate
provider data, rankings, indexing, citations, compliance, or causation.

## Verification

Validate source artifacts with their owning tool before interpretation. Run
the current repository's WebOps cross-reference validation when agent, skill,
tool, capability, or workflow mappings change.
'''

def main():
    for row in ROWS:
        folder=SKILLS/row[0]; folder.mkdir(exist_ok=True); (folder/"SKILL.md").write_text(render(row),encoding="utf-8")
    index=ROOT/"SKILLS_INDEX.md"; text=index.read_text(); marker="\n## WebOps skills\n"
    if marker in text: text=text.split(marker)[0].rstrip()+"\n"
    rows="\n".join(f'| `{name}` | {trigger[0].upper()+trigger[1:]}. | {sources} |' for name,trigger,sources,*_ in ROWS)
    index.write_text(text+marker+"\n| Skill | Use when | Primary sources |\n|---|---|---|\n"+rows+"\n",encoding="utf-8")
    expected=ROOT/"evals/expected-skill-map.md"; text=expected.read_text(); marker="\n## WebOps routing\n"
    if marker in text: text=text.split(marker)[0].rstrip()+"\n"
    rows="\n".join(f'| {trigger[0].upper()+trigger[1:]} | `{name}` |' for name,trigger,*_ in ROWS)
    expected.write_text(text+marker+"\n| Query theme | Expected skill(s) |\n|---|---|\n"+rows+"\n",encoding="utf-8")
    triggers_path=ROOT/"evals/trigger-queries.json"; triggers=json.loads(triggers_path.read_text())
    for name,trigger,*_ in ROWS:
        triggers[name]={"should_trigger":[f"Use {name} for {trigger}",f"I need help {trigger}"],"should_not_trigger":["write a generic Python hello world","summarize an unrelated PDF"]}
    triggers_path.write_text(json.dumps(triggers,indent=2)+"\n",encoding="utf-8")
    print(f"Generated {len(ROWS)} WebOps skills")

if __name__=="__main__": main()
